  _ = `主题活动：%1$s`,
  _ = `2022 年万圣节`,
  _ = `此活动是关于您游戏的 2022 年万圣节更新吗？如果您在游戏中为万圣节添加了新的地图、皮肤、艺术作品或其他内容，或是举办特别恐怖内容限时活动、挑战或其他相似活动，我们希望知晓。我们也在考虑其他方法来更好地向更广泛的受众显示主题活动，但我们首先需要更好地了解开发者在各自游戏中举办何种活动（如果有）来庆祝佳节。如果此活动是关于您游戏的 2022 年万圣节更新，请点击下方的“开启”。`,
  _ = `万圣节主题活动`,
  _ = `您要举办活动或添加万圣节主题的内容吗？请参见%1$s，了解更多关于携万圣节主题的游戏内活动参与 Steam 尖叫游戏节的信息。`,
