  _ = `宣布在您的游戏内开展限时万圣节主题活动，可以让玩家获得额外物品、奖励、福利、经验值等等。有开始和结束时间。`,
  _ = `Steam 大奖提名奖项`,
  _ = `请选择一个特定奖项，好让您的粉丝可以提名您的游戏角逐该奖项。他们可以在活动中直接为该奖项提名您的游戏！`,
  _ = `今年 Steam 大奖的多数奖项将颁给 %1$s 年（自 %2$s 上届 Steam 大奖提名以来）发行的游戏。鉴于您的游戏在该日期前发行，因此只有资格角逐“爱的付出”奖项。`,
  _ = `要想了解更多信息，并下载包含艺术作品模板的 Steam 大奖资产包用于市场营销，请参见<1>此处的文档</1>。`,
  _ = `此游戏不符合任何 Steam 大奖奖项的资格。如果您认为这样有误，请联系 <1>Steamworks 客服</1>。`,
  _ = `不可见商店页面确认`,
  _ = `appID %1$s 的商店页面当前不可见。发布此活动将会让用户知晓该游戏的存在。如果您还是选择发布此活动，必须在此处予以明确确认。`,
  _ = `即使商店页面不可见，仍然发布活动吗？`,
