  _ = `交叉推广背景`,
  _ = `绘制于此特卖（如“折扣与活动”页面）交叉推广栏目的后方。所有语言共用同一张图片。图片会经过裁剪以适应栏目大小并沿边缘铺满，因此请确保重要内容远离边缘，尤其是顶部和底部。`,
  _ = `至少为 %1$spx 宽 x %2$spx 高`,
  _ = `移除背景`,
  _ = `未上传背景。`,
  _ = `请选择徽标和游戏在桌面端的排列方式。在手机端，徽标始终位于游戏上方。`,
