  _ = `仅在交叉推广栏目中显示特卖徽标`,
  _ = `特卖页面和点数商店不会显示徽标。其他交叉推广此次特卖的页面仍会显示徽标。`,
  _ = `此特卖页面不会显示其徽标。徽标仅会出现在其他页面交叉推广此次特卖的位置。`,
  _ = `商店宣传图`,
  _ = `这些宣传图让商店在通常展示游戏的位置——精选和推荐轮播区、商店中心，以及购物车——展示此特卖页面。它们与游戏在其商店页面的图像资产选项卡下上传的宣传图相同，尺寸也相同。`,
  _ = `您可以一次性上传所有宣传图。当图片尺寸与某宣传图尺寸完全相同时，系统会自动将其分配给相关宣传图，而其余图片需由您自行分配并按提示进行裁剪。您可以将图片文件命名为以语言名称结尾，以便让图片按语言分类（如“main_capsule_french.jpg”）。`,
  _ = `将重点放在特卖的品牌上。请确保徽标清晰可辨。`,
  _ = `在整个商店的推荐栏目以及较窄的精选栏位中显示。`,
  _ = `尺寸很小，因此徽标必须在最小尺寸下也清晰可辨。`,
  _ = `用于整个商店的列表以及购物车中。`,
  _ = `为产品的营销而设计。请勿包含引语、评测的总体评价或奖项。 `,
  _ = `在首页顶部的精选和推荐轮播区中显示。`,
  _ = `一种竖向图像营销资产。请勿包含引语、评测的总体评价或奖项。`,
  _ = `可能会显示在季节性特卖的首页顶部，以及其他特卖页面上。`,
  _ = `库主页图片`,
  _ = `您的库资产过旧。请花一点时间来更新这些对您所有顾客可见的资产。`,
