  _ = `允许用户点击特卖页面徽标后转跳至商店的另一位置，例如首页。`,
  _ = `仅输入商店主页之后的地址部分，不要包含前导斜杠。例如，输入 category/pins_pegs 以链接至 https://store.steampowered.com/category/pins_pegs`,
  _ = `这必须是相对于商店主页的路径，因此请去掉前面的“https://store.steampowered.com/”。例如，输入 category/pins_pegs，而非 https://store.steampowered.com/category/pins_pegs`,
  _ = `去掉前导斜杠。例如，输入 category/pins_pegs，而非 /category/pins_pegs`,
  _ = `不能包含空格。例如，输入 category/pins_pegs`,
