  _ = `您的帐户受限。受限帐户无法保存活动内容。请参见 https://help.steampowered.com/zh-cn/faqs/view/71D3-35C2-AD96-AA3A，了解更多详情。`,
  _ = `栏目已标记为隐藏。正在显示背景组图片编辑预览。`,
  _ = `栏目已标记为隐藏至 %1$s。正在显示背景组图片编辑预览占位空间。`,
  _ = `栏目已标记为在 %1$s前隐藏。正在显示背景组图片编辑预览占位空间。`,
  _ = `因为栏目不在允许的国家/地区列表内，所以已标记为隐藏。正在显示背景组图片编辑预览占位空间。`,
