  _ = `导出和导入本地化文件，以管理您整个页面字符串的翻译。`,
  _ = `导出本地化文件…`,
  _ = `导出…`,
  _ = `我们支持以 CSV 或 XML 格式导出活动内容。`,
  _ = `逗号分隔文件（CSV）`,
  _ = `可扩展标记语言（XML）`,
  _ = `此操作将创建并下载“逗号分隔值”（CSV）文件，其中包含 Steam 支持的所有语言的字段，以及您之前输入的所有文本。`,
  _ = `请注意：在导入的文件中，您可以不包含自己不希望用导入的文件进行变更的任何语言。`,
  _ = `选择您偏好的格式来下载 CSV：`,
  _ = `下面将为有内容的语言分别下载 XML 文件。始终导出英文文件。`,
  _ = `注意：如果您有多个语言的内容，您的浏览器可能会警告您我们正在尝试下载多个文件。您应当允许此操作，因为我们会将每个语言保存至不同的 XML 文件中。`,
  _ = `导出 XML`,
  _ = `下载 CSV（每行一个语言）`,
  _ = `下载 CSV（每行一个内容字段）`,
  _ = `每行一个语言`,
  _ = `每列一个语言`,
  _ = `令牌，语言列表`,
  _ = `导入本地化文件…`,
  _ = `导入…`,
  _ = `选择一份或多份文件上传，为您的标题、副标题、概要及描述导入本地化文本。我们使用文件扩展名来确定导入的文件是 XML 还是 CSV 格式；对于 XML，我们使用文件名末端、扩展名之前的 API 语言代码来确定 XML 文件内容的语言。您应该先导出 CSV 或 XML 文件，以确保使用的是正确格式。`,
  _ = `本地化导入已完成。下列语言已更新：%1$s`,
  _ = `本地化导入已完成。未进行任何变更。`,
  _ = `无法解析或识别 CSV 文件。`,
  _ = `文件未含有“.xml”或“.csv”扩展名，无法解析文件名：%1$s`,
  _ = `文件名未指定 API 语言代码。文件名格式应为 <user name>_<language>.xml：%1$s`,
  _ = `解析和应用 XML 数据时出错：%1$s`,
  _ = `将英文草稿导出至 Crowdin，或者将所有其他语言从 Crowdin 导入。`,
  _ = `导出至 Crowdin`,
  _ = `是否将当前英文草稿上传至 Crowdin，并覆盖 Crowdin 中当前所有的英文字符串？`,
  _ = `从 Crowdin 导入`,
  _ = `从 Crowdin 上导入已翻译为下列语言的字符串吗？此操作将覆盖所有本地草稿。`,
  _ = `特卖页面已通过 Valve 审核，现实施以下限制。`,
  _ = `特卖页面的虚 URL 不再可编辑`,
  _ = `展示时可能会引用虚 URL，更改虚 URL 可能会导致链接失效。`,
  _ = `无法再向此特卖页面添加更多应用、程序包或捆绑包`,
  _ = `特卖页面审核针对的是包含的应用/程序包/捆绑包组合，无法再添加，但可以移动、重新排序和删除。`,
  _ = `不允许在特卖页面上进行更多更改。`,
  _ = `（仅限 Valve 使用）自动推送更新至 Crowdin`,
  _ = `尚未推送至 Crowdin`,
  _ = `启用后，对此活动的变更将在保存后推送到 Crowdin 进行本地化。将此功能保持为关闭直至您活动的文本已定稿并准备好进行本地化。如果您会在一段时间内进行大量编辑，请禁用此功能直至完成编辑为止，然后再重新启用。`,
  _ = `请记得在变更此设置后点击“保存”。`,
