  _ = `转换为文本链接`,
  _ = `预览图片`,
  _ = `当前活动发生以下错误，导致此活动无法发布。请修正并重试发布。`,
  _ = `活动开始时间未设置。`,
  _ = `活动（%1$s）开始时间已过。将开始时间调整为将来或设置为现在。如果允许发布过去时间的活动，近期访问您页面的用户可能会错过活动，因为其最后一次访问时间晚于活动的开始时间。`,
  _ = `此活动（%1$s）的开始时间早于允许时间。请将其设为 %2$s 或之后的时间。`,
  _ = `活动结束时间早于开始时间`,
  _ = `结束时间缺失：缺少必须设置的结束时间。`,
  _ = `当前的可见时间晚于活动开始时间，会使活动在开始时不可见。`,
  _ = `描述最多为 32,000 个字符。%1$s描述超过 32,000 个字符。`,
  _ = `存在%1$s活动标题，但活动描述缺失。对所支持的语言两者均需具备。`,
  _ = `存在%1$s活动描述，但活动标题缺失。对所支持的语言两者均需具备。`,
  _ = `活动不具备任何语言的标题或描述。`,
  _ = `已设置此活动在蒸汽平台显示，但缺失 %1$s 语言的标题和描述`,
  _ = `您必须提供至少用于英语的关键艺术作品才能发布“重大更新”类型的活动。重大更新将在游戏桌面库详情的显著位置显示。`,
  _ = `您必须至少提供英语封面图片才能发布“%1$s”类型的活动。`,
  _ = `您必须至少提供简体中文-蒸汽平台封面图片，才能发布“%1$s”类型的活动。`,
  _ = `一个特卖只能有一个单一的选项卡区域`,
  _ = `此游戏的商店页面当前不可见。您必须在“选项”选项卡上予以确认后才能发布。`,
  _ = `%1$s选项卡缺失 %3$s 个必填字段中的 %2$s 个。`,
  _ = `以下针对当前活动的警告可以绕过，不会妨碍发布，但是建议您修正。`,
  _ = `缺失英语活动描述和/或英语活动名称。英语为许多 Steam 用户的主要语言或替代语言，不提供英语将极大限制活动对 Steam 顾客的可见性。`,
  _ = `缺失艺术作品。活动允许自定义艺术作品，以协助打造活动品牌，增强对 Steam 用户的吸引力。如果没有艺术作品，我们将用游戏宣传图代替。`,
  _ = `缺失艺术作品。活动允许自定义艺术作品，以协助打造活动品牌，增强对 Steam 用户的吸引力。如果没有艺术作品，我们将用组头像代替。`,
  _ = `活动类型设置为“其他”，将极大地降低此活动的可见性。Steam 根据活动类型来决定向哪些 Steam 顾客显示该活动。“其他”属于影响力最小的类型，会向最小数量的用户展示。`,
  _ = `在 %2$s 个语言中，%1$s 个有副标题。建议提供所有语言的副标题译文。`,
  _ = `在 %2$s 个语言中，%1$s 个有该语言专用的艺术作品。如果艺术作品无需本地化，忽略此项没有问题。对于没有艺术作品的语言，将以英语使用的艺术作品替代。`,
  _ = `可见时间已调整为过去，因此现在保存将使活动可见。一旦活动可见，开始时间将无法更改，活动也无法隐藏。`,
  _ = `已为活动上传商店焦点图片，但焦点标记未启用。焦点标记必须由 Valve 启用，方可在您的商店页面商显示横幅。`,
  _ = `促销页面 logo 的目标 URL 未采取相对于商店主页的格式，因此点击该 logo 会将顾客导向一个无效页面。它应该类似于 category/pins_pegs，而非 https://store.steampowered.com/category/pins_pegs`,
  _ = `找到此类型的多个栏目`,
  _ = `此特卖页面包含至少一个与此栏目类型相同的其他栏目。此栏目本来应该只在单一特卖页面上使用一次。确定需要此类型的多个栏目吗？`,
