  _ = `管理 %1$s 张图片`,
  _ = `在您的详情页面中添加内容丰富的形象图，以传达更新或公告的主题或本质。请注意，下载模板（链接位于本页顶部）非常重要，这样才能确保形象图的设计适合各种使用情境。`,
  _ = `您详情页面的预览：`,
  _ = `您活动弹出页面的预览：`,
  _ = `此图片会在您直播旁的侧面板显示。`,
  _ = `重要活动或公告可以包含于活动持续期间在您商店页面上显示的横幅图像。此横幅的艺术作品独立于商店其他地方的艺术作品。这些横幅需要由 Valve 批准。请在上传前联系您的 Valve 联系人。`,
  _ = `请仔细计划在您的焦点横幅上纳入一段简短上口的活动描述，这样玩家一眼就可以看到活动的令人兴奋之处。`,
  _ = `您可以使用整个图片空间，并将您自己对更新或活动的描述添加到图片当中。`,
  _ = `这是上方商店焦点的移动版，会在用户于较窄屏幕上查看焦点时使用。`,
  _ = `此图片会作为特卖页面的背景显示。您可以创作一幅大型图片，也可以创建磁贴并将其设置为重复图案。`,
  _ = `关键内容应该放置在您图片中央的 940px 之内。艺术作品可以按需超出至两侧及页面下方。一般而言，最好让艺术作品向两侧和底部渐变至纯色，然后设置相匹配的页面背景色。请保持图片小于 4MB。`,
  _ = `下载所有特卖页面模板（.psd 文件）`,
  _ = `特卖背景图片与下方指定的特卖页面徽标相得益彰。如果一起使用，您的特卖页面徽标将浮动在背景顶部。`,
  _ = `模板`,
  _ = `此图片将叠加在您页面顶部的背景之上。如果您希望图片本地化，请通过电子邮件发送 .psd 文件给您的 Valve 联络人。`,
  _ = `如果提供，则所有加入此特卖活动的游戏将在其商店页面显示此横幅。横幅会在特卖活动期间持续显示，最长两周。注意此横幅在使用前必须由 Valve 批准，且不得使用动图效果。`,
  _ = `只有当页面分辨率为适应移动版显示而降低时才会显示此版本。`,
  _ = `您也可以用更新、公告、季或其他活动的品牌元素更新您的库主页图片。请访问商店页管理中的“图像资产”选项卡进行更新。`,
  _ = `设计`,
  _ = `尺寸`,
  _ = `用途`,
  _ = `必需`,
  _ = `可选`,
  _ = `此图片通常包含代表您活动的艺术作品和品牌元素，以及您想引起大家注意的任何简短消息。在某些情况下，Steam 会在此图片旁边自动包含您的游戏名称和图标，但您或许也会想在封面图片中包含游戏徽标，因为在社交媒体上分享您的活动时会使用此图片。`,
  _ = `宣传图将显示在您商店页面上的近期公告中、活动与公告的列表里，以及您的库详情页面上。宣传图在社交媒体上推广时，用于代表您的活动。图片也用于链接至您的活动/公告，并可能会与来自多款游戏的内容共同显示，因此图片应该清晰可辨。`,
  _ = `此图片通常包含代表您发行商、开发者或系列作品的艺术作品及品牌元素。在某些情况下，Steam 会在此图片旁自动包含您的头像图标。`,
  _ = `图片会在 Steam 中此创作者主页出现的地方展示，并在社交媒体上推广时用于代表该活动。图片应该清晰可辨。`,
  _ = `年度最佳的横幅图片，连接至 Steam 榜单`,
  _ = `绘制于此特卖（如“折扣与活动”页面）交叉推广栏目的后方，用来替代特卖页面徽标。如果此徽标无需本地化，只需上传一次英文版即可，所有语言均将使用英文版。`,
  _ = `徽标会在特卖页面顶部区域于背景图片上渲染。此图片应包含活动徽标、活动日期及任意的标语，且具有透明背景。`,
